// Minimal base64 decoder (no external deps).
int B64Val(char c) {
  if (c >= 'A' && c <= 'Z') return c - 'A';
  if (c >= 'a' && c <= 'z') return c - 'a' + 26;
  if (c >= '0' && c <= '9') return c - '0' + 52;
  if (c == '+') return 62;
  if (c == '/') return 63;
  return -1;
}

std::vector<std::uint8_t> B64Decode(const char* s, std::size_t len) {
  std::vector<std::uint8_t> out;
  out.reserve(len / 4 * 3 + 3);
  int vals[4];
  std::size_t n = 0;
  for (std::size_t i = 0; i < len; ++i) {
    int v = B64Val(s[i]);
    if (v < 0) continue;
    vals[n++] = v;
    if (n == 4) {
      out.push_back(static_cast<std::uint8_t>((vals[0] << 2) | (vals[1] >> 4)));
      out.push_back(static_cast<std::uint8_t>((vals[1] << 4) | (vals[2] >> 2)));
      out.push_back(static_cast<std::uint8_t>((vals[2] << 6) | vals[3]));
      n = 0;
    }
  }
  return out;
}

